import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.charset.Charset;
import java.util.List;

public class DocumentTest {

    @Test
    public void createShell_DocumentShouldBeReturned() {
        String baseUri = "https://example.com";
        Document document = Document.createShell(baseUri);
        assertNotNull(document);
    }

    @Test
    public void location_ReturnsCorrectLocation() {
        String baseUri = "https://example.com";
        Document document = new Document(baseUri);
        assertEquals(baseUri, document.location());
    }

    @Test
    public void connection_ReturnsCorrectConnection() {
        Connection connection = Jsoup.connect("https://example.com");
        Document document = new Document(connection.baseUrl());
        assertNotNull(document.connection());
    }

    @Test
    public void head_ReturnsCorrectHeadElement() {
        String baseUri = "https://example.com";
        Document document = new Document(baseUri);
        Element head = document.head();
        assertNotNull(head);
    }

    @Test
    public void body_ReturnsCorrectBodyElement() {
        String baseUri = "https://example.com";
        Document document = new Document(baseUri);
        Element body = document.body();
        assertNotNull(body);
    }

    @Test
    public void forms_ReturnsCorrectFormsElements() {
        String baseUri = "https://example.com";
        Document document = new Document(baseUri);
        List<FormElement> forms = document.forms();
        assertTrue(forms.size() > 0);
    }

    @Test
    public void expectForm_ReturnsCorrectFormElement() {
        String cssQuery = "#form";
        String baseUri = "https://example.com";
        Document document = new Document(baseUri);
        FormElement form = document.expectForm(cssQuery);
        assertNotNull(form);
    }

    @Test
    public void title_ReturnsCorrectTitle() {
        String baseUri = "https://example.com";
        Document document = new Document(baseUri);
        String title = document.title();
        assertTrue(title != null && !title.isEmpty());
    }

    @Test
    public void charset_ReturnsCorrectCharset() {
        Charset charset = Charset.forName("UTF-8");
        Document document = new Document(charset.name());
        assertEquals(charset, document.charset());
    }

    @Test
    public void updateMetaCharsetElement_SetsCorrectValue() {
        boolean update = true;
        Document document = new Document();
        document.updateMetaCharsetElement(update);
        assertTrue(document.metaCharsetElement().equals(update));
    }

    @Test
    public void createElement_ReturnsCorrectElement() {
        String tagName = "div";
        Document document = new Document();
        Element element = document.createElement(tagName);
        assertNotNull(element);
        assertEquals(tagName, element.tagName());
    }

    @Test
    public void outerHtml_ReturnsCorrectOuterHtml() {
        String html = "<html><body>Hello World!</body></html>";
        Document document = Jsoup.parse(html);
        assertEquals(html, document.outerHtml());
    }

    @Test
    public void text_ReturnsCorrectText() {
        String text = "Hello World!";
        Document document = new Document();
        Element element = document.text(text);
        assertNotNull(element);
        assertEquals(text, element.data());
    }

    @Test
    public void nodeName_ReturnsCorrectNodeName() {
        String nodeName = "html";
        Document document = Jsoup.parse("<html></html>");
        assertEquals(nodeName, document.nodeName());
    }
}
